// Build-time only: Prisma remains available for legacy read/export tooling.
// The Workers runtime imports only these explicit generated schema artifacts.
import { Prisma } from "@prisma/client";
import { access, mkdir, writeFile } from "node:fs/promises";

const models = Prisma.dmmf.datamodel.models;
const metadata = {};
const source = [
  '// Generated by scripts/generate-d1.mjs from the legacy schema; review changes with migrations.',
  'import { sqliteTable, text, integer } from "drizzle-orm/sqlite-core";',
  'import type { InferSelectModel } from "drizzle-orm";',
];
const ddl = [];
for (const model of models) {
  const name = model.name[0].toLowerCase() + model.name.slice(1);
  metadata[name] = { name: model.name, fields: model.fields };
  const fields = [], columns = [];
  for (const f of model.fields) {
    let column = ["Int", "Boolean", "DateTime"].includes(f.type) ? "INTEGER" : "TEXT";
    let builder = f.type === "DateTime" ? `integer("${f.name}", { mode: "timestamp_ms" })`
      : f.type === "Boolean" ? `integer("${f.name}", { mode: "boolean" })`
      : f.type === "Int" ? `integer("${f.name}")` : `text("${f.name}")`;
    if (f.isId) { column += " PRIMARY KEY"; builder += ".primaryKey()"; }
    if (f.isRequired) { column += " NOT NULL"; builder += ".notNull()"; }
    if (f.hasDefaultValue && typeof f.default !== "object") {
      const value = typeof f.default === "boolean" ? Number(f.default) : f.default;
      column += ` DEFAULT ${typeof value === "string" ? "'" + value.replaceAll("'", "''") + "'" : value}`;
      builder += `.default(${JSON.stringify(f.default)})`;
    }
    columns.push(`  "${f.name}" ${column}`);
    fields.push(`  ${f.name}: ${builder},`);
  }
  source.push(`export const ${name} = sqliteTable("${model.name}", {\n${fields.join("\n")}\n});`);
  ddl.push(`CREATE TABLE IF NOT EXISTS "${model.name}" (\n${columns.join(",\n")}\n);`);
  for (const f of model.fields.filter(f => f.isUnique))
    ddl.push(`CREATE UNIQUE INDEX IF NOT EXISTS "${model.name}_${f.name}_key" ON "${model.name}" ("${f.name}");`);
  for (const fields of model.uniqueFields)
    ddl.push(`CREATE UNIQUE INDEX IF NOT EXISTS "${model.name}_${fields.join("_")}_key" ON "${model.name}" (${fields.map(f => `"${f}"`).join(",")});`);
  // Every owner query is indexed, in addition to relationship/date lookups.
  for (const f of model.fields.filter(f => f.name === "ownerId" || /Id$/.test(f.name) || f.name === "date"))
    ddl.push(`CREATE INDEX IF NOT EXISTS "${model.name}_${f.name}_idx" ON "${model.name}" ("${f.name}");`);
}
source.push(`export const tables = { ${Object.keys(metadata).join(", ")} };`);
source.push('export type User = InferSelectModel<typeof user>;');
source.push('export type TableName = keyof typeof tables;');
ddl.push('CREATE TABLE IF NOT EXISTS "StoreRevision" ("id" INTEGER PRIMARY KEY CHECK (id = 1), "revision" INTEGER NOT NULL);',
  'INSERT OR IGNORE INTO "StoreRevision" VALUES (1, 0);',
  'CREATE TABLE IF NOT EXISTS "LoginAttempt" ("id" TEXT PRIMARY KEY, "count" INTEGER NOT NULL, "until" INTEGER NOT NULL);');
await mkdir("d1/migrations", { recursive: true });
await writeFile("src/server/schema.ts", source.join("\n") + "\n");
await writeFile("src/server/fields.json", JSON.stringify(metadata, null, 2) + "\n");
try {
  await access("d1/migrations/0001_domain.sql");
  console.log("Kept existing d1/migrations/0001_domain.sql; add a new incremental migration instead.");
} catch {
  await writeFile("d1/migrations/0001_domain.sql", ddl.join("\n") + "\n");
}
console.log(`Generated ${models.length} D1 domain tables; no source database was opened.`);
